import { runScenario } from "./claim-office.js";

const readStdin = (): Promise<string> =>
  new Promise((resolve) => {
    let input = "";

    process.stdin.on("data", (chunk) => (input += chunk));
    process.stdin.on("end", () => resolve(input));
  });

// Writes the scenario outcome to stdout. Nothing else in this file writes to
// stdout, so the "no results on stdout when the run fails" contract holds as
// long as failures propagate out of here rather than being handled inside.
const main = async (): Promise<void> => {
  const outcome = runScenario(JSON.parse(await readStdin()));

  process.stdout.write(JSON.stringify(outcome));
};

await main();
